/* GENERATED by `lake exe emitHostC --sstore` (Evm.CL.SstoreGasC). DO NOT EDIT.
 *
 * The five SSTORE gas schedules, for a host that has neither Lisp nor the
 * emitted assembly: every plan in Evm.CL.ARM64.SstoreGasDenote is a function
 * of seven booleans and a refund counter that only enters as
 *
 *     refund' = ((refund + add1) - sub) + add2        (saturating subtract)
 *
 * so each schedule is a TABLE over those seven bits. `rows_match_the_plans`
 * and `applyRow_is_each_plan` prove the tables are the spec's; the only
 * unproved step is that the two helpers below implement `applyRow`, which
 * c/test_sstore_gas.c checks against Lean's own plans.
 *
 * Link this INSTEAD of the emitted assembly, never alongside it: both define
 * the same five symbols. c/Makefile uses it for rv32 only.
 */
#include <stdint.h>
#include "evm_state.h"
#include "generated/limb_ops.h"

typedef struct { uint32_t cost, add1, sub, add2; } EitaSstoreRow;

/* The bit order is x86-64's packed register (Evm.CL.X86SstoreGas), so all
   three derivations agree on what a pattern number means. The comparisons
   are the EMITTED ones from generated/limb_ops.h, not a copy. */
static inline unsigned eita_sstore_bits(const u256_t *orig, const u256_t *cur,
                                        const u256_t *nv, uint64_t cold) {
    return (unsigned)(limb_is_zero(orig->limb)
                      | (limb_is_zero(cur->limb) << 1)
                      | (limb_is_zero(nv->limb)  << 2)
                      | (limb_eq(orig->limb, cur->limb) << 3)
                      | (limb_eq(cur->limb,  nv->limb)  << 4)
                      | (limb_eq(orig->limb, nv->limb)  << 5)
                      | ((cold ? 1 : 0)                 << 6));
}

/* `applyRow`: the subtraction SATURATES, and sits between the two additions
   because eip2200's chain clamps in the middle and cannot be folded. */
static inline uint64_t eita_sstore_apply(uint64_t refund, const EitaSstoreRow *r) {
    const uint64_t r1 = refund + r->add1;
    return (r1 < r->sub ? 0u : r1 - r->sub) + r->add2;
}

